INSERT INTO FIXER_PROFILE (
	USER_ID, FIXER_NO, FIXER_APPROVAL, FIXER_INTRO, FIXER_CAREER
) VALUES (
	#{userId}, SEQ_FIXER_PROFILE.NEXTVAL, 'PENDING', #{fixerIntro}, #{fixerCareer}
)

INSERT INTO FIXER_LICENSE (
	LICENSE_ID, FIXER_ID, LICENSE_NAME, LICENSE_NO, LICENSE_FILE, ISSUED_AT
) VALUES (
	SEQ_FIXER_LICENSE.NEXTVAL, #{fixerId}, #{licenseName},
	#{licenseNo}, #{licenseFile}, #{issuedAt}
)
